function extractDocNumber(docName) {
  if (!docName) return null;
  const dashMatch = docName.match(/\s-\s([A-Z]?-?\d{4}-?\d+)$/i);
  if (dashMatch) return dashMatch[1];
  const hashMatch = docName.match(/#([A-Z]?-?\d{4}-?\d+)/i);
  if (hashMatch) return hashMatch[1];
  const yearMatch = docName.match(/(\d{4}-\d{3,5})/);
  if (yearMatch) return yearMatch[1];
  const numMatch = docName.match(/(\d{5,})\s*$/);
  if (numMatch) return numMatch[1];
  return null;
}

function extractFirstName(fullName) {
  if (!fullName) return null;
  const parts = fullName.trim().split(/\s+/);
  return parts[0] || null;
}

function shortenCompany(company) {
  if (!company || company === 'Privat') return null;
  if (company.length <= 20) return company;
  return company.substring(0, 18).trim() + '...';
}

function fillTemplate(template, vars) {
  let result = template;
  for (const [key, val] of Object.entries(vars)) {
    if (val) {
      result = result.replace(new RegExp('\\$\\{' + key + '\\}', 'g'), val);
    }
  }
  result = result.replace(/\$\{[^}]+\}/g, '').replace(/\s+/g, ' ').trim();
  return result;
}

