function generateSubject(sKat, fuNum, docNum, firstName, shortCompany) {
  const vars = { num: docNum, name: firstName, firma: shortCompany };
  const templates = docNum ? SUBJ_TEMPLATES[sKat] : SUBJ_FALLBACK[sKat];
  const fallbackTemplates = SUBJ_FALLBACK[sKat];
  const idx = Math.min(fuNum - 1, templates.fu.length - 1);
  let template = templates.fu[idx] || fallbackTemplates.fu[idx];
  let subject = fillTemplate(template, vars);
  if (!subject || subject.length < 10) {
    subject = docNum ? `NEONTRIP Angebot ${docNum}` : `NEONTRIP - Ihr LED-Angebot`;
  }
  return subject;
}

