function isAllowedCustomerOfferLink(link) {
  if (!link || typeof link !== 'string') return false;
  try {
    const url = new URL(link);
    if (url.protocol !== 'https:') return false;
    if (url.hostname === 'angebote.neontrip.de') return /^\/offer\/[^/?#]+$/i.test(url.pathname);
    if (/(^|\.)pandadoc\.com$/i.test(url.hostname)) return true;
    return false;
  } catch (e) {
    return false;
  }
}

const selectedOfferLink = item.offer_link || item.neontrip_offer_link || item.document_link || item.pandadoc_customer_link || null;
const hasValidLink = isAllowedCustomerOfferLink(selectedOfferLink);

// PRODUCTS + SPECS prefetched from Check PandaDoc Status (no AI tool roundtrip)
let productLines = '(Produktdetails nicht verfuegbar - referenziere generisch als "LED-Neonschild")';
try {
  const pdDoc = $('Check PandaDoc Status').item.json;
  const tables = (pdDoc && pdDoc.pricing && pdDoc.pricing.tables) || [];
  const variants = [];
  for (const t of tables) {
    for (const it of (t.items || [])) {
      if (!it || !it.name) continue;
      // Filter Standard-Zubehoer (Dimmer/Fernbedienung/Wandmontage) - sind Standard, nie erwaehnen
      if (/dimmer|fernbedienung|wandmontage|wandhalterung|standard.?versand|versand.?standard/i.test(it.name)) continue;
      const cleanedName = String(it.name).replace(/\s*inkl\.\s*\d+\s*%\s*(Rabatt|rabatt)\s*/gi, ' ').replace(/\s+/g, ' ').trim();
      if (!cleanedName) continue;
      const desc = String(it.description || '').replace(/\r/g, '').trim();
      if (desc) {
        const specs = desc.split('\n').map(s => s.trim()).filter(s => s.length > 0).slice(0, 4).join(' | ');
        variants.push('- ' + cleanedName + ': ' + specs);
      } else {
        variants.push('- ' + cleanedName);
      }
    }
  }
  const uniq = Array.from(new Set(variants)).slice(0, 5);
  if (uniq.length > 0) productLines = uniq.join('\n');
} catch (e) {}

// TELEFONAT / DEAL-NOTIZEN aus ActiveCampaign (Placetel + manuelle Notizen)
let dealNotizen = '(Keine Telefonat-Notizen vorhanden)';
try {
  const notesResp = $('Fetch AC Deal Notes').first();
  const noteArr = notesResp && notesResp.json && Array.isArray(notesResp.json.notes) ? notesResp.json.notes : [];
  if (noteArr.length > 0) {
    const texts = noteArr.slice(0, 3).map(n => {
      let text = (n && n.note ? String(n.note) : '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\r/g, '').replace(/\s+/g, ' ').trim();
      if (text.length > 600) text = text.substring(0, 600) + '...';
      const date = (n && n.cdate) ? String(n.cdate).substring(0, 10) : '';
      return text.length > 10 ? (date ? '[' + date + '] ' + text : text) : '';
    }).filter(t => t.length > 0);
    if (texts.length > 0) dealNotizen = texts.join('\n---\n');
  }
} catch (e) {}

