function getNextFollowupDelayHours(sKat, currentFuNum, isUrgent) {
  const schedules = {
    // Delay after FU1, FU2, FU3, FU4, FU5
    S1: [24, 72, 120, 240, 504],   // High urgency: 1d, 3d, 5d, 10d, 21d
    S2: [48, 96, 168, 336, 720],   // B2B normal: 2d, 4d, 7d, 14d, 30d
    S3: [24, 72, 144],             // Privat/B2C: 1d, 3d, 6d; maxFU=4
    S4: [120, 240, 504, 840, 1440] // Formal: 5d, 10d, 21d, 35d, 60d
  };
  const arr = schedules[sKat] || schedules.S2;
  let delay = arr[currentFuNum - 1] || 168;
  if (isUrgent && sKat !== 'S1') delay = Math.max(24, Math.round(delay * 0.75));
  return delay;
}

function normalizeFollowupSendTime(date, sKat) {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) return date;

  const isB2C = sKat === 'S3';
  const startHour = isB2C ? 10 : 9;
  const startMinute = 30;
  const endHour = isB2C ? 20 : 17;
  const endMinute = isB2C ? 0 : 30;

  const minutes = d.getHours() * 60 + d.getMinutes();
  const startMinutes = startHour * 60 + startMinute;
  const endMinutes = endHour * 60 + endMinute;

  if (minutes < startMinutes) {
    d.setHours(startHour, startMinute, 0, 0);
  } else if (minutes > endMinutes) {
    d.setDate(d.getDate() + 1);
