function ensureReadableParagraphs(text) {
  let cleaned = String(text || '').replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
  if (!cleaned) return cleaned;
  if (cleaned.includes('\n\n')) return cleaned;

  const linkMatch = cleaned.match(/https?:\/\/\S+/);
  if (linkMatch && linkMatch.index > 20) {
    const before = cleaned.slice(0, linkMatch.index).trim();
    const after = cleaned.slice(linkMatch.index).trim();
    if (before && after) return before + '\n\n' + after;
  }

  const sentences = cleaned.match(/[^.!?]+[.!?]+(?:\s|$)|[^.!?]+$/g);
  if (sentences && sentences.length >= 3) {
    const first = sentences.slice(0, 2).join('').trim();
    const rest = sentences.slice(2).join('').trim();
    if (first && rest) return first + '\n\n' + rest;
  }
  return cleaned;
}

