  const hashMatch = docName.match(/#([A-Z]?-?\d{4}-?\d+)/i);
  if (hashMatch) return hashMatch[1];
  const yearMatch = docName.match(/(\d{4}-\d{3,5})/);
  if (yearMatch) return yearMatch[1];
  const numMatch = docName.match(/(\d{5,})\s*$/);
  if (numMatch) return numMatch[1];
  return null;
}

