// ERROR HANDLER v3.1 - MIT FAILED-NOTIFICATION
const input = $input.first().json;

let originalData = {};
try {
  const guardData = $('Guard OK?')?.first()?.json;
  const parseData = $('Parse + Guard')?.first()?.json;
  const buildData = $('Build Prompt')?.first()?.json;
  originalData = guardData || parseData || buildData || {};
} catch (e) {
  originalData = {};
}

const retryCount = (originalData.retry_count || 0) + 1;
const maxRetries = 3;

const errMsg = input.error?.message || input.message || input.errorMessage || 'Unknown error';
const errString = String(errMsg).toLowerCase();

// Detect API/Network errors (should be retried)
const isApiError = errString.includes('econnreset') || 
                   errString.includes('timeout') || 
                   errString.includes('connection') ||
                   errString.includes('pandadoc') ||
                   errString.includes('network') ||
                   errString.includes('enotfound') ||
                   errString.includes('etimedout');

// Detect critical errors (should fail immediately)
const isCriticalError = errString.includes('unauthorized') ||
                        errString.includes('forbidden') ||
                        errString.includes('document not found') ||
                        errString.includes('invalid document');

let newStatus;
let rescheduleMinutes;
let shouldNotify = false;

if (isCriticalError) {
  newStatus = 'failed';
  rescheduleMinutes = null;
  shouldNotify = true;
  console.log(`[ERROR] Critical error detected - marking as failed: ${originalData.id}`);
} else if (isApiError && retryCount < maxRetries) {
  newStatus = 'pending';
  rescheduleMinutes = Math.min(15 * Math.pow(2, retryCount - 1), 120);
  console.log(`[ERROR] API error - retry ${retryCount}/${maxRetries} in ${rescheduleMinutes}min: ${originalData.id}`);
} else if (retryCount >= maxRetries) {
  newStatus = 'failed';
  rescheduleMinutes = null;
  shouldNotify = true;
  console.log(`[ERROR] Max retries reached - marking as failed: ${originalData.id}`);
} else {
  newStatus = 'pending';
  rescheduleMinutes = 15;
  console.log(`[ERROR] Standard error - retry in ${rescheduleMinutes}min: ${originalData.id}`);
}

const newSchedule = rescheduleMinutes ? new Date(Date.now() + rescheduleMinutes * 60000) : null;

return [{
  json: {
    id: originalData.id || null,
    new_status: newStatus,
    new_scheduled_for: newSchedule ? newSchedule.toISOString() : null,
    final_retry_count: retryCount,
    error_message: String(errMsg).substring(0, 1000),
    error_type: isApiError ? 'api_error' : (isCriticalError ? 'critical_error' : 'other_error'),
    skip_update: !originalData.id,
    should_notify: shouldNotify,
    customer_name: originalData.customer_name || 'Unbekannt',
    customer_email: originalData.customer_email || 'Unbekannt',
    followup_type: originalData.followup_type || 'Unbekannt',
    item_id: originalData.id
  }
}];

