// Guard Failed Handler v2.2 - SKIP Items nicht an Recovery weiterleiten
const items = $input.all();

// Guard: If no items, just pass through empty
if (!items || items.length === 0) {
  console.log('[GUARD] No items received - skipping');
  return [];
}

const results = [];
for (const inputItem of items) {
  const item = inputItem.json;

  // FIX v2.2: If do_not_send is true (SKIP detected), don't pass to recovery
  // These items should NOT be sent under any circumstances
  if (item.do_not_send === true || item.passed_guard === false) {
    console.log(`[SKIP] Item ${item.id} marked do_not_send or failed guard - will NOT be sent. Reason: ${item.skip_reason || 'guard_failed'}`);
    continue;
  }

  // Check if offer link is missing
  const hasLink = (item.pandadoc_customer_link && item.pandadoc_customer_link.startsWith('http')) || 
                  (item.document_link && item.document_link.startsWith('http'));

  if (!hasLink) {
    // Missing offer link - try recovery
    console.log(`[RECOVERY] NO OFFER LINK - Will try Supabase recovery: ${item.id || 'unknown'} | Customer: ${item.customer_email || 'unknown'}`);
    results.push({ 
      json: { 
        ...item,
        guard_failed: true, 
        failed_reason: 'no_offer_link',
        should_mark_failed: true
      } 
    });
  } else {
    // Has link but guard failed for unknown reason
    console.log(`[WARN] Guard failed but has link - skipping: ${item.id || 'unknown'}`);
    continue;
  }
}

if (results.length === 0) {
  console.log('[GUARD] All items filtered out - nothing to recover');
  return [];
}

return results;

// Bereitet die Outlook-Suche vor
// FIX v2: Hole originale Queue-Daten aus Normalize Claim mit Fallback
// PREPARE_REPLY_CHECK_NEONTRIP_BYPASS_20260615:
// NEONTRIP offer links intentionally skip the old PandaDoc status node.
let pandadocResponse = {};
try {
  pandadocResponse = $('Check PandaDoc Status').first().json || {};
} catch (e) {
  pandadocResponse = $input.first().json || {};
}

// Versuche Daten aus Normalize Claim zu holen (mit Fallback)
let item;
try {
  const normalizedData = $('Normalize Claim').first();
  if (normalizedData && normalizedData.json) {
    item = normalizedData.json;
  } else {
    item = pandadocResponse;
  }
} catch (e) {
  // Fallback auf Input-Daten wenn Normalize Claim nicht erreichbar
  item = pandadocResponse;
}

// Merge PandaDoc Status mit Queue-Daten
let offerResolution = {};
try {
  offerResolution = $('Select NEONTRIP Offer Link').first().json || {};
} catch (e) {}

const mergedItem = { 
  ...item,
  legacy_pandadoc_customer_link: offerResolution.legacy_pandadoc_customer_link || item.legacy_pandadoc_customer_link || null,
  neontrip_offer_id: offerResolution.neontrip_offer_id || item.neontrip_offer_id || null,
  neontrip_offer_number: offerResolution.neontrip_offer_number || item.neontrip_offer_number || null,
  neontrip_offer_status: offerResolution.neontrip_offer_status || item.neontrip_offer_status || null,
  neontrip_offer_link: offerResolution.neontrip_offer_link || item.neontrip_offer_link || null,
  offer_link: offerResolution.offer_link || item.offer_link || item.document_link || item.pandadoc_customer_link || null,
  offer_link_source: offerResolution.offer_link_source || item.offer_link_source || null,
  document_link: offerResolution.document_link || item.document_link || null,
  pandadoc_customer_link: offerResolution.pandadoc_customer_link || item.pandadoc_customer_link || null,
  pandadoc_status: pandadocResponse.status,
  pandadoc_response_id: pandadocResponse.id,
  pandadoc_name: pandadocResponse.name
};

// Extrahiere Kunden-Email
const customerEmail = mergedItem.customer_email || mergedItem.email || null;
const followupId = mergedItem.id;
const quoteId = mergedItem.quote_id || mergedItem.pandadoc_id || mergedItem.document_id || null;

if (!customerEmail) {
  // Keine Email vorhanden - direkt zum Versand
  return [{
    json: {
      ...mergedItem,
      reply_check: {
        has_customer_email: false,
        action: 'send',
        reason: 'no_customer_email'
      }
    }
  }];
}

// Suche nach Emails vom Kunden in den letzten 7 Tagen
const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

return [{
  json: {
    ...mergedItem,
    reply_check: {
      has_customer_email: true,
      customer_email: customerEmail,
      search_from: sevenDaysAgo.toISOString(),
      followup_id: followupId,
      quote_id: quoteId
    }
  }
}];

// Analyze customer replies defensively and always return n8n item objects.
const base = $input.first()?.json || $('Prepare Reply Check').first()?.json || {};
let replies = [];
try {
  replies = $('Fetch Customer Replies').all().map(item => item.json).filter(Boolean);
} catch (e) {
  replies = [];
}

const texts = [];
for (const reply of replies) {
  const subject = reply.subject || reply.conversationTopic || '';
  const from = reply.from?.emailAddress?.address || reply.sender?.emailAddress?.address || reply.from || '';
  const received = reply.receivedDateTime || reply.sentDateTime || reply.createdDateTime || '';
  const body = reply.bodyPreview || reply.preview || reply.text || reply.body?.content || '';
  const line = [received, from, subject, body].filter(Boolean).join(' | ').trim();
  if (line) texts.push(line.substring(0, 1200));
}

const replyText = texts.slice(0, 5).join('\n---\n');
return [{
  json: {
    ...base,
    reply_check: {
      has_reply: replyText.length > 0,
      reply_count: replies.length,
      reply_text: replyText,
      checked_at: new Date().toISOString()
    }
  }
}];

// Baut den Prompt für die KI-Klassifizierung
const item = $input.first().json;
const replyText = item.reply_check.reply_text;
const customerName = item.customer_name || item.contact_name || 'Kunde';

const systemPrompt = `Du bist ein Vertriebsassistent für NEONTRIP, ein Unternehmen das LED Neon Schilder verkauft.
Analysiere die Kundenantwort und klassifiziere sie in EINE der folgenden Kategorien:

1. CANCEL - Kunde hat abgesagt, kein Interesse mehr, zu teuer, anderes Angebot angenommen
2. PURCHASED - Kunde hat bereits gekauft/bestellt (bei uns oder woanders)
3. NEEDS_TIME - Kunde braucht mehr Zeit zum Nachdenken, ist unentschlossen
4. RESCHEDULE - Kunde bittet darum, sich später zu melden ("melden Sie sich in X Wochen")
5. INTERESTED - Kunde hat Fragen, zeigt Interesse, möchte mehr Infos
6. UNCLEAR - Antwort ist unklar, neutral oder unverständlich

Für RESCHEDULE: Extrahiere auch die gewünschte Wartezeit in Tagen.

Antworte NUR im JSON-Format:
{"category": "CATEGORY", "reschedule_days": 0, "confidence": 0.9, "reason": "kurze Begründung"}`;

const userPrompt = `Kundenname: ${customerName}\n\nKundenantwort(en):\n${replyText}\n\nKlassifiziere diese Antwort.`;

return [{
  json: {
    ...item,
    classification_request: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 200,
      system: systemPrompt,
      messages: [
        {
          role: 'user',
          content: userPrompt
        }
      ]
    }
  }
}];

// Parst die Claude-Klassifizierung und bestimmt die Aktion
const originalItem = $('Build Classification Prompt').first().json;
const claudeResponse = $input.first().json;

// Check if the Classify Reply node returned an error
const isApiError = claudeResponse.error || claudeResponse.$error || !claudeResponse;

let classification;
let action = 'send'; // SAFE DEFAULT
let rescheduleDays = 0;
let cancelReason = null;

if (isApiError) {
  classification = {
    category: 'API_ERROR',
    confidence: 0,
    reason: 'Classify Reply API error - defaulting to send'
  };
  action = 'send';
} else {
  try {
    const responseText = claudeResponse.message?.content?.[0]?.text || 
                         claudeResponse.content?.[0]?.text ||
                         claudeResponse.text || 
                         JSON.stringify(claudeResponse);

    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      classification = JSON.parse(jsonMatch[0]);
      if (!classification.category) {
        throw new Error('No category field in response');
      }
    } else {
      throw new Error('No JSON found');
    }
  } catch (e) {
    classification = {
      category: 'UNCLEAR',
      reschedule_days: 0,
      confidence: 0.5,
      reason: 'Could not parse response: ' + e.message
    };
  }

  switch (classification.category?.toUpperCase()) {
    case 'CANCEL':
    case 'PURCHASED':
      action = 'cancel';
      cancelReason = classification.category?.toUpperCase() === 'PURCHASED' ? 'already_purchased' : 'customer_declined';
      break;

    case 'NEEDS_TIME':
      action = 'reschedule';
      rescheduleDays = 7;
      break;

    case 'RESCHEDULE':
      action = 'reschedule';
      rescheduleDays = classification.reschedule_days || 14;
      break;

    case 'INTERESTED':
    case 'UNCLEAR':
    default:
      action = 'send';
      break;
  }
}

// TOP-LEVEL routing_action fuer den Switch (vermeidet nested property Bug)
return [{
  json: {
    ...originalItem,
    routing_action: action,
    id: originalItem.id,
    document_id: originalItem.document_id,
    document_name: originalItem.document_name,
    customer_name: originalItem.customer_name,
    customer_email: originalItem.customer_email,
    customer_company: originalItem.customer_company,
    segment: originalItem.segment,
    anrede: originalItem.anrede,
    is_urgent: originalItem.is_urgent,
    budget_tier: originalItem.budget_tier,
    visual_style: originalItem.visual_style,
    decision_window_hours: originalItem.decision_window_hours,
    value: originalItem.value,
    currency: originalItem.currency,
    followup_type: originalItem.followup_type,
    followup_number: originalItem.followup_number,
    scheduled_for: originalItem.scheduled_for,
    status: originalItem.status,
    pandadoc_customer_link: originalItem.pandadoc_customer_link,
    pandadoc_status: originalItem.pandadoc_status,
    reply_check: originalItem.reply_check,
    reply_action: {
      action: action,
      classification: classification,
      reschedule_days: rescheduleDays,
      cancel_reason: cancelReason,
      customer_reply_text: originalItem.reply_check?.reply_text || ''
    }
  }
}];

