// PARSE AC DEAL STATUS v1.2 (Code v1 - no task runner)
// Extracts deal status from AC API response
// Merges with original claim data from Normalize Claim
// v1.2: Added Won check (status=1) in addition to Lost (status=2)

const acResponse = items[0].json;

let originalItem = {};
try {
  const normItems = $items('Normalize Claim');
  if (normItems && normItems.length > 0) {
    originalItem = normItems[0].json;
  }
} catch (e) {
  originalItem = {};
}

const deals = acResponse.deals || [];
let dealLost = false;
let acDealId = null;
let acDealStatus = null;
let cancelReason = null;

if (deals.length > 0) {
  // Match specific deal by NerdyFormsID (request_id) in deal title
  const requestId = originalItem.request_id || '';
  let matchedDeal = null;
  if (requestId) {
    matchedDeal = deals.find(d => d.title && d.title.includes(requestId));
  }
  // Fallback: neuester Deal wenn keine request_id oder kein Match
  const deal = matchedDeal || deals[0];
  acDealId = deal.id || null;
  acDealStatus = deal.status || '0';
  const isClosed = String(acDealStatus) === '1' || String(acDealStatus) === '2';
  if (isClosed) {
