function extractText(resp) {
  if (!resp || typeof resp !== 'object') return typeof resp === 'string' ? resp : '';
  if (resp.error) {
    aiError = true;
    const err = typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error));
    throw new Error('AI error: ' + err.substring(0, 250));
  }
  if (Array.isArray(resp.content) && resp.content[0]) {
    const first = resp.content[0];
    if (typeof first === 'string') return first;
    if (typeof first.text === 'string') return first.text;
  }
  if (resp.message && Array.isArray(resp.message.content) && resp.message.content[0]) {
    const first = resp.message.content[0];
    if (typeof first === 'string') return first;
    if (typeof first.text === 'string') return first.text;
  }
  if (resp.choices && resp.choices[0] && resp.choices[0].message && typeof resp.choices[0].message.content === 'string') {
    return resp.choices[0].message.content;
  }
  if (typeof resp.text === 'string') return resp.text;
  if (typeof resp.content === 'string') return resp.content;
  return JSON.stringify(resp);
}

function humanReview(reason, confidence = 1.0) {
  return {
    action: 'human_review',
    reason: reason.substring(0, 500),
    customer_replied: null,
    customer_question_open: null,
    internal_reply_after_customer: null,
    intent: 'unknown',
    delay_until: null,
    confidence
  };
}

function validateDelayUntil(value) {
  if (!value) return { ok: false, reason: 'delay action without delay_until' };
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return { ok: false, reason: 'delay_until is not a valid ISO date' };
  const now = new Date();
  if (date <= now) return { ok: false, reason: 'delay_until is not in the future' };
  const max = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
  if (date > max) return { ok: false, reason: 'delay_until is more than 30 days in the future' };
  return { ok: true, iso: date.toISOString() };
}

if (ctxItem.ec_outlook_error) {
  decision = humanReview('Outlook fetch error (' + (ctxItem.ec_outlook_error_reason || 'unknown') + ') — manual review required', 1.0);
} else {
  try {
    rawText = extractText(aiResp);
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON object found in response');
    const parseInput = jsonMatch[0].trim().replace(/^\`\`\`(?:json)?\s*/m, '').replace(/\`\`\`\s*$/m, '').trim();
    decision = JSON.parse(parseInput);
  } catch (e) {
    parseError = !aiError;
    console.log('[EC PARSE ERROR]', e.message, 'raw:', String(rawText).substring(0, 300));
    decision = humanReview(e.message, 1.0);
