if (isTestSend) {
  originalAction = 'send';
  decision.original_action = 'send';
  decision.action = 'human_review';
  decision.reason = 'Test send blocked: AI decided send, but test addresses must never reach Outlook Send Email.';
  decision.confidence = conf;
