// Build NEONTRIP offer lookup from stable identifiers.
const item = $json || {};

function clean(value) {
  const text = String(value || '').trim();
  return text || null;
}

function extractDocNumber(docName) {
  const text = clean(docName);
  if (!text) return null;
  const dashMatch = text.match(/\s-\s([A-Z]?-?\d{4}-?\d+)$/i);
  if (dashMatch) return dashMatch[1];
  const hashMatch = text.match(/#([A-Z]?-?\d{4}-?\d+)/i);
  if (hashMatch) return hashMatch[1];
  const yearMatch = text.match(/(\d{4}-\d{3,5})/);
  if (yearMatch) return yearMatch[1];
  const numMatch = text.match(/(A\/N\s*\d+|\d{5,})\s*$/i);
  if (numMatch) return numMatch[1];
  return null;
}

function extractTrelloCardId(value) {
  const text = clean(value);
  if (!text) return null;
  const direct = text.match(/\b[a-f0-9]{24}\b/i);
  if (direct) return direct[0];
  const urlMatch = text.match(/\/c\/([A-Za-z0-9]+)/);
  return urlMatch ? urlMatch[1] : null;
}

const trelloCardId =
  extractTrelloCardId(item.trelloCardId) ||
  extractTrelloCardId(item.trello_card_id) ||
  extractTrelloCardId(item.card_id) ||
  extractTrelloCardId(item.cardId) ||
  extractTrelloCardId(item.trello_card_url) ||
  extractTrelloCardId(item.card_url);

const offerNumber =
  clean(item.offerNumber) ||
  clean(item.offer_number) ||
  clean(item.document_number) ||
  extractDocNumber(item.document_name);

const documentReference =
  clean(item.documentReference) ||
  clean(item.document_reference) ||
  clean(item.nerdy_forms_id) ||
  clean(item.request_id);

const customerEmail = clean(item.customer_email || item.email);

let query = null;
let source = 'none';
if (trelloCardId) {
  query = trelloCardId;
  source = 'trelloCardId';
} else if (offerNumber) {
  query = offerNumber;
  source = 'offerNumber';
} else if (documentReference) {
  query = documentReference;
  source = 'documentReference';
} else if (customerEmail) {
  query = customerEmail.toLowerCase();
  source = 'customerEmailFallback';
