function isAllowedCustomerLink(link) {
  if (!link || typeof link !== 'string') return false;
  const value = String(link).trim();

  // FOLLOWUP_LINK_GUARD_REGEX_FIRST_20260615:
  // n8n Code sandbox can fail URL parsing; accept the exact public offer shape first.
  if (/^https:\/\/angebote\.neontrip\.de\/offer\/[^/?#]+$/i.test(value)) return true;

  try {
    const url = new URL(value);
    if (url.protocol !== 'https:') return false;
    if (url.hostname === 'angebote.neontrip.de') {
      return /^\/offer\/[^/?#]+$/i.test(url.pathname);
    }
    if (/(^|\.)pandadoc\.com$/i.test(url.hostname)) return true;
    return false;
  } catch (e) {
    return false;
  }
}

function isNeontripOfferUrl(link) {
  return /^https:\/\/angebote\.neontrip\.de\/offer\/[^/?#]+$/i.test(String(link || ''));
}

function sameEmail(left, right) {
  return String(left || '').trim().toLowerCase() === String(right || '').trim().toLowerCase();
}

if (isInternalCustomerEmail(customerEmail)) {
  return fail('internal_customer_email_blocked');
}

if (response.error || response.code === 'UNAUTHORIZED' || response.message === 'Unauthorized') {
  if (source !== 'none') return fail('neontrip_offer_lookup_failed', { neontrip_offer_lookup_error: response.error || response.message || response.code || 'unknown' });
}

const results = Array.isArray(response.results) ? response.results : [];

let relevant = results.filter((offer) => offer && isNeontripOfferUrl(offer.publicUrl));

if (strongLookup) {
  relevant = relevant.filter((offer) => offer.matchType === 'exact');
} else if (emailFallback) {
  relevant = relevant.filter((offer) => offer.matchType === 'contact' && sameEmail(offer.customerEmail, customerEmail));
} else {
  relevant = [];
}

const closedMatches = relevant.filter((offer) => CLOSED.has(offer.status));
const draftMatches = relevant.filter((offer) => offer.status === 'DRAFT');
const sendableMatches = relevant.filter((offer) => SENDABLE.has(offer.status));

if (closedMatches.length > 0) {
  return fail('neontrip_offer_closed_no_followup', {
    neontrip_offer_closed: true,
    neontrip_offer_closed_statuses: closedMatches.map((offer) => offer.status)
  });
}

if (sendableMatches.length > 1) {
  return fail('ambiguous_neontrip_offer_mapping', {
    neontrip_offer_match_count: sendableMatches.length,
    neontrip_offer_candidates: sendableMatches.map((offer) => ({
      offerId: offer.offerId,
      offerNumber: offer.offerNumber,
      documentReference: offer.documentReference,
      trelloCardId: offer.trelloCardId,
      status: offer.status,
      matchType: offer.matchType,
      matchReasons: offer.matchReasons
    }))
  });
}

if (sendableMatches.length === 1) {
  const offer = sendableMatches[0];
  const publicUrl = offer.publicUrl;
  if (!isAllowedCustomerLink(publicUrl)) {
    return fail('neontrip_offer_link_not_customer_safe', { neontrip_offer_candidate_url: publicUrl });
  }

  console.log('[OFFER LINK] NEONTRIP offer selected | source=' + source + ' | status=' + offer.status + ' | queue=' + (item.id || '?'));
  return [{
    json: {
      ...item,
      legacy_pandadoc_customer_link: item.pandadoc_customer_link || item.document_link || null,
      neontrip_offer_id: offer.offerId,
      neontrip_offer_number: offer.offerNumber,
      neontrip_offer_status: offer.status,
      neontrip_offer_link: publicUrl,
      offer_link: publicUrl,
      offer_link_source: 'neontrip_offers',
      document_link: publicUrl,
      pandadoc_customer_link: publicUrl,
      do_not_send: false,
      passed_guard: true
    }
  }];
}

if (draftMatches.length > 0) {
  return fail('neontrip_offer_draft_not_sendable', {
    neontrip_offer_match_count: draftMatches.length,
    neontrip_offer_candidates: draftMatches.map((offer) => ({
      offerId: offer.offerId,
      offerNumber: offer.offerNumber,
      documentReference: offer.documentReference,
      trelloCardId: offer.trelloCardId,
      status: offer.status,
      matchType: offer.matchType,
      matchReasons: offer.matchReasons
    }))
  });
}

const fallbackLink = item.offer_link || item.document_link || item.pandadoc_customer_link || item.quote_link || item.share_link || null;
if (fallbackLink && !isAllowedCustomerLink(fallbackLink)) {
  return fail('fallback_offer_link_not_customer_safe', { fallback_offer_link: fallbackLink });
}

return [{
  json: {
    ...item,
    offer_link: fallbackLink || null,
    offer_link_source: fallbackLink ? 'pandadoc_fallback' : 'none',
    document_link: fallbackLink || item.document_link || null,
    pandadoc_customer_link: fallbackLink || item.pandadoc_customer_link || null,
    do_not_send: false,
    passed_guard: true
  }
}];
